  "scenario_id": "sc-f69eea",
  "overall_assessment": "anomalies",
  "findings": [
    {
      "benefit": "Death",
      "years": [
        2015,
        2024
      ],
      "pattern": "drift",
      "direction": "increase",
      "magnitude": "A/E rises from ~0.63-0.66 in early years to ~1.26-1.31 in 2023-2024; fitted trend ~+0.084 A/E per year; early 2015-2018 A/E=0.656 vs late 2021-2024 A/E=1.199",
      "confidence": 0.95,
      "evidence": [
        "artifacts/ae_death_by_year.csv: 2015 AE=0.626, 2016 AE=0.701, 2017 AE=0.637, 2018 AE=0.660; expected counts are 240-390, so sampling sd is only ~1/sqrt(expected)=0.064-0.051, making these far below baseline.",
        "artifacts/ae_death_by_year.csv: 2023 AE=1.261 and 2024 AE=1.307; expected counts are 735 and 826, so sampling sd is ~0.037-0.035, making these far above baseline.",
        "summary.json: Death overall_AE=1.004, indicating the early under-claiming and later over-claiming offset in the aggregate and hide a strong time trend."
      ],
      "recommended_action": "Investigate Death claims data completeness and reporting lag for 2015-2018, and claim volume/frequency changes for 2021-2024. Check exposure definition, age/gender mix, policy mix, coding/settlement basis, and any changes in expected mortality. Review against benchmarks/Death.csv and exposure.csv. If genuine, update mortality trend assumptions in pricing, valuation, and reserve setting."
    }
  ]
}

